<script setup lang="ts">
import{onMounted,reactive,ref}from'vue'
import{crearContrato,descargarContrato,listarCentros,listarContratos,listarProvincias,type Contrato,type Option}from'../services/contratos'
const rows=ref<Contrato[]>([]),companies=ref<Option[]>([]),departments=ref<Option[]>([]),provinces=ref<Option[]>([]),towns=ref<Option[]>([]),criterion=ref(''),companyFilter=ref(0),page=ref(1),last=ref(1),total=ref(0),loading=ref(false),saving=ref(false),modal=ref(false),error=ref(''),success=ref(''),file=ref<File|null>(null),department=ref(0),province=ref(0),selectedTowns=ref<number[]>([]),territories=ref<{province:Option;towns:Option[]}[]>([])
const form=reactive({empresa_id:0,titulo:'',fecha:new Date().toISOString().slice(0,10)})
async function load(target=1){page.value=target;loading.value=true;error.value='';try{const result=await listarContratos(criterion.value,companyFilter.value,target);rows.value=result.data;total.value=result.total;last.value=result.last_page;companies.value=result.options.empresas;departments.value=result.options.departamentos}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(){Object.assign(form,{empresa_id:0,titulo:'',fecha:new Date().toISOString().slice(0,10)});department.value=province.value=0;provinces.value=[];towns.value=[];selectedTowns.value=[];territories.value=[];file.value=null;modal.value=true;error.value=''}
async function changeDepartment(){province.value=0;towns.value=[];selectedTowns.value=[];provinces.value=department.value?await listarProvincias(department.value):[]}
async function changeProvince(){selectedTowns.value=[];towns.value=province.value?await listarCentros(province.value):[]}
function addTerritory(){const provinceItem=provinces.value.find(x=>x.id===province.value);if(!provinceItem||!selectedTowns.value.length){error.value='Seleccione una provincia y al menos un centro poblado.';return}const chosen=towns.value.filter(x=>selectedTowns.value.includes(x.id));const existing=territories.value.find(x=>x.province.id===province.value);if(existing){const ids=new Set(existing.towns.map(x=>x.id));chosen.forEach(x=>{if(!ids.has(x.id))existing.towns.push(x)})}else territories.value.push({province:provinceItem,towns:chosen});selectedTowns.value=[];error.value=''}
function removeTerritory(id:number){territories.value=territories.value.filter(x=>x.province.id!==id)}
function pick(event:Event){const selected=(event.target as HTMLInputElement).files?.[0]||null;if(selected&&!/\.(pdf|docx?)$/i.test(selected.name)){error.value='Solo se admiten archivos PDF, DOC o DOCX.';file.value=null;return}file.value=selected}
async function save(){if(!form.empresa_id||!form.titulo.trim()||!form.fecha||!file.value||!territories.value.length){error.value='Complete EPS, título, fecha, archivo y ámbito territorial.';return}const provinceIds=territories.value.map(x=>x.province.id),townIds=territories.value.flatMap(x=>x.towns.map(t=>t.id));if(!townIds.length){error.value='Agregue al menos un centro poblado.';return}saving.value=true;try{await crearContrato({...form,archivo:file.value,provincias:provinceIds,centros_poblados:townIds});success.value='Contrato de explotación registrado correctamente.';modal.value=false;await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / ENKI / Contratos de Explotación</nav><header class="hero"><div class="mark">CE</div><div><small>ENKI · ÁMBITO TERRITORIAL</small><h1>Contratos de explotación</h1><p>Documentos contractuales, provincias y centros poblados comprendidos.</p></div><strong>{{total}} contratos</strong><button @click="open">+ Nuevo contrato</button></header><div v-if="success" class="flash good">✓ {{success}}</div><div v-if="error" class="flash bad">{{error}}</div><section class="filters"><label>Buscar contrato<input v-model.trim="criterion" placeholder="Título" @keyup.enter="load()"></label><label>EPS<select v-model.number="companyFilter"><option :value="0">Todas</option><option v-for="item in companies" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><button @click="load()">Buscar</button><button class="clear" @click="criterion='';companyFilter=0;load()">Limpiar</button></section><div v-if="loading" class="empty">Cargando contratos…</div><div v-else-if="!rows.length" class="empty">No hay contratos de explotación registrados.</div><section v-else class="cards"><article v-for="item in rows" :key="item.id"><header><span>DOC</span><div><small>CONTRATO #{{item.id}} · {{item.fecha}}</small><h2>{{item.titulo}}</h2></div></header><div class="body"><dl><div><dt>EPS</dt><dd>{{item.empresa}}</dd></div><div><dt>Provincias</dt><dd>{{item.provincias.length}}</dd></div><div><dt>Centros poblados</dt><dd>{{item.centros_poblados.length}}</dd></div></dl><div class="tags"><span v-for="provinceItem in item.provincias" :key="provinceItem.id">{{provinceItem.nombre}}</span></div><details><summary>Ver centros poblados</summary><p>{{item.centros_poblados.map(x=>x.nombre).join(', ')||'Sin centros poblados'}}</p></details></div><footer><button @click="descargarContrato(item)">Descargar contrato</button></footer></article></section><footer v-if="last>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button :disabled="page>=last" @click="load(page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVO CONTRATO</small><h2>Registrar contrato de explotación</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>EPS *<select v-model.number="form.empresa_id"><option :value="0">Seleccione</option><option v-for="item in companies" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Fecha *<input v-model="form.fecha" type="date"></label><label class="wide">Título *<input v-model.trim="form.titulo" maxlength="255"></label><label class="wide">Archivo PDF, DOC o DOCX *<input type="file" accept=".pdf,.doc,.docx" @change="pick"></label></div><h3>Ámbito territorial</h3><section class="territory-picker"><label>Departamento<select v-model.number="department" @change="changeDepartment"><option :value="0">Seleccione</option><option v-for="item in departments" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Provincia<select v-model.number="province" :disabled="!department" @change="changeProvince"><option :value="0">Seleccione</option><option v-for="item in provinces" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Centros poblados<select v-model="selectedTowns" :disabled="!province" multiple><option v-for="item in towns" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><button type="button" @click="addTerritory">Agregar ámbito</button></section><div class="territories"><article v-for="item in territories" :key="item.province.id"><div><b>{{item.province.nombre}}</b><small>{{item.towns.map(x=>x.nombre).join(', ')}}</small></div><button type="button" @click="removeTerritory(item.province.id)">×</button></article></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar contrato'}}</button></footer></form></div></div></template>
<style scoped>.page{--a:#148f92;color:#35474d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:13px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.5rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.2rem}.hero p{margin:0;color:#7c898f;font-size:.6rem}.hero strong{margin-left:auto;font-size:.48rem}.hero button,.filters button,.pages button,.cards footer button,.modal footer button,.territory-picker>button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.46rem}.flash{padding:10px;font-size:.58rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1.5fr 1fr auto auto;align-items:end;gap:7px;background:#fff}.filters label,.modal label{font-size:.45rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;background:#fff;font:inherit;font-size:.49rem}.clear{color:#68767c!important;background:#edf1f2!important}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.cards article{border-top:3px solid var(--a);border-radius:9px;background:#fff}.cards article>header{padding:13px;display:flex;gap:8px;border-bottom:1px solid #e7eced}.cards header>span{width:34px;height:34px;display:grid;place-items:center;border-radius:7px;color:#8f3e43;background:#fae9ea;font-size:.42rem;font-weight:800}.cards h2{margin:2px 0;font-size:.68rem}.cards small{color:#89949a;font-size:.38rem}.body{padding:13px}.body dl{margin:0}.body dl div{padding:4px 0;display:flex;border-bottom:1px solid #edf0f1;font-size:.43rem}.body dd{margin-left:auto}.tags{margin-top:8px;display:flex;flex-wrap:wrap;gap:4px}.tags span{padding:3px 6px;border-radius:9px;color:#287275;background:#e3f3f3;font-size:.38rem}.body details{margin-top:8px;font-size:.42rem}.body details p{color:#6f7d83}.cards article>footer{padding:0 13px 13px}.cards footer button{width:100%}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.57rem}.pages{display:flex;justify-content:center;align-items:center;gap:9px;font-size:.47rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(780px,100%);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.85rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.grid{margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.wide{grid-column:span 2}.modal h3{margin:15px 0 6px;font-size:.58rem}.territory-picker{padding:10px;display:grid;grid-template-columns:1fr 1fr 1.3fr auto;align-items:end;gap:6px;background:#f5f8f8}.territory-picker select[multiple]{height:70px}.territories article{padding:8px;display:flex;border-bottom:1px solid #e5eaeb;font-size:.43rem}.territories b,.territories small{display:block}.territories small{color:#7f8c91}.territories button{margin-left:auto;border:0;color:#a13e43;background:none}.modal>footer{margin-top:14px;display:flex;justify-content:flex-end;gap:5px}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.territory-picker{grid-template-columns:1fr 1fr}}@media(max-width:580px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.cards,.grid,.territory-picker{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
